insert into public.cpl_memory (slug, kind, org, title, summary, detail, plain, tags, affects, source, related, author, event_date, status, verified_by)
values
('sam-public-library-malone-look-2026-10-24', 'decision', 'cpl', 'Sam: the public CPL Library leaves First Light for the look of Malone''s CPL/AI page; simpler, sorted Most recent, Light by default', 'Sam, 2026-10-24 ~15:20Z: "see the page Malone designed with you for the AI Outcomes to Skills project. I like the look of it and it seems consistent with the CO webpages. Can you depart from our First Light motif and redesign the CPL Public Library based on Malone''s."', 'His other words, the same message: "Simplify: cut the things I lined through on the screenshot and move the For filter up to the right of the search box. Add a Sort control with ''Most recent'' as the default. Include less of the text descriptions in each card to allow the cards to be shorter--use ... on the end of the text if needed. Open in Light by default: dark only when the viewer clicks Dark, never from the device setting." And: "You can have the right hand student image cycle through a selection of any images here: https://careereducationtoolkit.cccco.edu/assets/photography/." His markup struck the eyebrow (California Community Colleges · CPL Initiative), the description, the kind and audience word filters, the "The library" label and the header''s CPL Library link, with an arrow moving For beside the search. Malone''s page: map.rccd.edu/CPL-AI. CLAUDE.md''s First Light rule now names the public library as its one departure.', 'Sam asked for the public library to look like Malone''s page for the CPL/AI project, which matches the Chancellor''s Office websites, and to be simpler, sorted newest first, and light unless the reader picks dark.', array['library','public-library','design','first-light','sam-ruling']::text[], array['library/index.html','library/public_library.js','tests/public_library.test.js','CLAUDE.md']::text[], 'Sam in chat, S467, 2026-10-24 ~15:20Z, with his marked-up screenshot of the page', array['library-made-for-built-2026-10-23','sam-library-public-listing-with-team-phrase-2026-10-23']::text[], 'SkyHollyleaf-S467', '2026-10-24', 'verified', 'Sam (his ask in chat, 2026-10-24)'),
('public-library-malone-look-built-2026-10-24', 'milestone', 'cpl', 'The public library in Malone''s look is built: For beside the search, Sort, two-line cards, Light by default, a cycling hero photo', 'Built by S467 on 2026-10-24 on claude/keen-darwin-fre94u: navy Georgia title over a gold rule, search and For in the hero, a photo in a CSS arc, Sort opening on Most recent, cards clamped to one occasion line and two summary lines, no device-setting query, the photo cycling with Pause photos. tests/public_library.test.js 103 checks; a11y clean in light and dark.', 'Mock-up https://claude.ai/artifact/1eotDvtmj56cHMEFP363T2 (the real page with the sixteen pieces listed 2026-10-24). Each new check was mutation-tested: a device-dark media block, the default sort, the clamp, ignoring reduced motion, the eyebrow, For moved away, a raw color in a rule, the header self-link, the header reading the device and a dark default each fail their check. The hero art on Malone''s page is a 424 by 445 screenshot crop with the arc, a black right edge and part of her notice bar baked in; the page uses a crop clean of all three, upscaled twice with Lanczos, drawn inside a CSS ellipse. The photo list is the .hero-slide images in library/index.html; one today, so nothing moves until the toolkit photos arrive (Open Asks Sheet 124 card 1).', 'The simpler public library Sam asked for is built and tested; it shows one photo until the photos he named can be fetched.', array['library','public-library','design','a11y']::text[], array['library/index.html','library/public_library.js','library/photos/hero-student-1.jpg','a11y.config.js']::text[], 'cpl-project-tracker branch claude/keen-darwin-fre94u (S467); docs/reference/lanes/library.md', array['sam-public-library-malone-look-2026-10-24']::text[], 'SkyHollyleaf-S467', '2026-10-24', 'proposed', null),
('careereducationtoolkit-unreachable-from-sessions-2026-10-24', 'fact', 'cpl', 'careereducationtoolkit.cccco.edu answers neither the cloud environment nor Anthropic''s web fetcher', '2026-10-24 ~15:25Z: curl through the environment''s proxy got CONNECT 403 for careereducationtoolkit.cccco.edu, and WebFetch got getaddrinfo ENOTFOUND, so the name does not resolve publicly; the photo site may answer only inside the CO''s or Sam''s network. The library''s hero photos wait on Open Asks Sheet 124 card 1.', 'Web search found no page on the host either. Allowing it under the environment''s Network access helps only if the name is public; photos attached to a session''s message work either way.', 'The photo website Sam named cannot be reached from a cloud session, so the photos have to come from him.', array['library','public-library','network','photos']::text[], array['library/index.html']::text[], 'S467 tool results, 2026-10-24 (curl via the agent proxy; WebFetch)', array['public-library-malone-look-built-2026-10-24']::text[], 'SkyHollyleaf-S467', '2026-10-24', 'proposed', null),
('a11y-harness-reads-transparent-stop-as-black-2026-10-24', 'pitfall', 'cpl', 'The a11y harness reads a gradient''s transparent stop as black', 'scripts/a11y.js scores text on a gradient at its worst stop and parses each rgba() stop without its alpha, so `transparent` (rgba(0,0,0,0)) counts as #000000: navy text on the library''s white hero read 1.56:1. Fade a gradient to a zero-alpha copy of its own color, rgba(205,226,245,0); it also renders the cleaner fade.', 'Found by S467 on 2026-10-24: the library hero''s radial glow ended in transparent. After the change both themes pass at nine widths. The harness stays as it is; the finding is about how gradients are written.', 'The accessibility checker mistakes a see-through gradient end for black, so a gradient should fade to a see-through copy of its own color.', array['a11y','harness','css','pitfall']::text[], array['scripts/a11y.js','library/index.html']::text[], 'S467 run of npm run a11y -- public-library public-library-dark, 2026-10-24', array['public-library-malone-look-built-2026-10-24']::text[], 'SkyHollyleaf-S467', '2026-10-24', 'proposed', null)
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
